/** Find firmen whose primary_kategorie OR any kategorie matches the needle (case-insensitive). */
export function firmenByCategory(needle: string): Firma[] {
  const lc = needle.toLowerCase();
  return firmen.filter((f) =>
    f.primary_kategorie.toLowerCase().includes(lc) ||
    f.kategorien.some((k) => k.toLowerCase().includes(lc)),
  );
}
